  "48 种数据模式覆盖表格、记录、列表、层级、指标、计划、地图与操作。排序、选择、展开、列管理、筛选和视图切换都有统一运行时。": "テーブル、レコード、リスト、階層、インジケーター、プラン、マップ、操作をカバーする 48 のデータ モード。並べ替え、選択、展開、列管理、フィルタリング、およびビュー切り替えのための統合されたランタイムがあります。",
  "48 种数据展示与操作模式 + 8 类复用交互": "48 種類のデータ表示および操作モード + 8 種類の再利用インタラクション",
