  "5 个平台档案、28 个稳定组件包和 506 个组件归属映射，让开发者与 AI 可以直接选择正式产物，不再临时拆 CSS。语法级压缩、Source Map、SHA-256/SRI 完整性、可复现构建、TypeScript 类型、跨版本兼容基线与发布包门禁随构建一起交付。": "5 つのプラットフォーム ファイル、28 の安定したコンポーネント パッケージ、および 506 のコンポーネント所有権マッピングにより、開発者と AI は一時的に CSS を逆アセンブルすることなく公式製品を直接選択できます。構文レベルの圧縮、ソース マップ、SHA-256/SRI の整合性、再現可能なビルド、TypeScript タイピング、バージョン間の互換性ベースライン、およびリリース パッケージ ゲーティングがビルドとともに提供されます。",
