  "安全区、动态视口、顶部栏、底部导航、Bottom/Action/Filter Sheet、下拉刷新、无限加载、滑动操作、滚轮选择、键盘避让、移动认证与结算、权限和离线状态都有稳定契约，可直接用于移动网页、PWA 和 Tauri/Electron 移动式 WebView。": "セーフ エリア、ダイナミック ビューポート、トップ バー、ボトム ナビゲーション、ボトム/アクション/フィルター シート、プルして更新、無限ロード、スライド操作、ホイール選択、キーボード回避、モバイル認証と決済、権限とオフライン ステータスには安定した契約があり、モバイル Web ページ、PWA および Tauri/Electron モバイル WebView に直接使用できます。",
