  "按内容宽度折叠的侧栏；size / content-min / gap": "サイドバーがコンテンツの幅に合わせて折りたたまれました。サイズ/コンテンツ最小/ギャップ",
  "按钮、链接、焦点与选中状态自动跟随主题。": "ボタン、リンク、フォーカス、および選択された状態は自動的にテーマに従います。",
  "按钮菜单；Arrow、Home、End、Escape": "ボタンメニュー;矢印、ホーム、エンド、エスケープ",
  "按平台/组件生成": "プラットフォーム/コンポーネントごとに生成",
