  "标签、按钮、元数据自动换行；gap / align / justify": "ラベル、ボタン、メタデータのラップ。ギャップ / 整列 / 位置揃え",
  "标签、分段/选择、全屏对话框、Snackbar": "タグ、セグメント化/選択、全画面ダイアログ、スナックバー",
  "标签、分栏、Dock、检查器和状态栏都保持高密度、小圆角和完整键盘路径。": "ラベル、列、ドック、インスペクター、ステータス バーはすべて、高密度、小さな丸い角、および完全なキーボード パスを維持します。",
  "标签搜索、创建与多选": "タグの検索、作成、複数選択",
  "标题": "タイトル",
  "标题和操作分居两端并可换行；gap / align": "タイトルとアクションは両端で分離されており、折り返すことができます。隙間/整列",
  "标题栏、活动栏、工作台、检查器与状态栏。": "タイトル バー、アクティビティ バー、ワークベンチ、インスペクター、ステータス バー。",
  "标准发布": "標準リリース",
  "标准页面宽度与自适应左右留白。": "標準のページ幅と適応型の左右の余白。",
  "标准桌面": "標準デスクトップ",
  "表": "テーブル",
  "表达 Dirty、Saving、Saved 和 Error，并支持延迟保存及立即保存。": "ダーティ、保存、保存、エラーを表現し、遅延保存と即時保存をサポートします。",
  "表单、导航、浮层、数据、媒体、商业、通信、法律、工作流和 Dashboard 均有稳定结构与状态约定。": "フォーム、ナビゲーション、オーバーレイ、データ、メディア、ビジネス、コミュニケーション、法律、ワークフロー、ダッシュボードはすべて、安定した構造と状態規約を持っています。",
  "表单不再从一堆 Input 开始": "フォームが大量の入力で始まらなくなりました",
  "表单传统组合": "伝統的な組み合わせを形成する",
  "表单传统组合清单": "従来の組み合わせリストを作成する",
  "表单区": "フォーム領域",
  "表单组合": "フォームの組み合わせ",
  "表格": "テーブル",
  "表格、列表和卡片视图切换": "テーブル、リスト、カードビューの切り替え",
  "表面": "表面",
  "并排": "サイドバイサイド",
  "并排/统一差异及增删语义": "並列/統合された相違点と追加および削除のセマンティクス",
  "不强制裁切的通用比例盒": "強制切断のないユニバーサルプロポーショナルボックス",
  "不是缩小桌面，而是完整的移动应用层": "小さなデスクトップではなく、完全なモバイル アプリ層",
  "不要再为下一张页面重新发明基础设施。": "次のページに向けてインフラストラクチャを再発明するのはやめてください。",
  "不要在 Renderer 开启 Node Integration，也不要向页面暴露任意 IPC。适配器只接受 minimize、maximize、close、drag 白名单动作。": "レンダラーでノード統合を有効にせず、IPC をページに公開しないでください。アダプターは、ホワイトリストの最小化、最大化、閉じる、およびドラッグのアクションのみを受け入れます。",
  "不遮挡内容的补充优先使用 Help Text、Inline Hint 或 Tip；必须绑定控件时使用 Tooltip；包含链接和操作时使用 Help Popover；跨步骤教学使用 Tour。不要把重要错误或必须阅读的法律信息藏进悬浮层。": "コンテンツをブロックしない補足コンテンツには、ヘルプ テキスト、インライン ヒント、またはヒントを使用します。コントロールをバインドする必要がある場合はツールチップを使用します。リンクや操作を含める場合はヘルプ ポップオーバーを使用します。ツアーをクロスステップティーチングに使用します。重要なエラーや必読の法的情報をフローティング レイヤーに隠さないでください。",
  "布局": "レイアウト",
  "布局、表单、导航、数据、内容、账号、商业、移动、桌面和 AI 均可独立引入。": "レイアウト、フォーム、ナビゲーション、データ、コンテンツ、アカウント、コマース、モバイル、デスクトップ、AI はすべて独立して導入できます。",
  "布局使用逻辑属性，组件覆盖 RTL 下的动画方向与箭头。": "レイアウトは論理プロパティを使用し、コンポーネントは RTL でアニメーションの方向と矢印をオーバーライドします。",
  "布局系统": "レイアウトシステム",
