  "打印时 Reel、Scroll Area、Scroll Snap、Masonry、Imposter、Overlay 和 Sticky Region 自动展平，避免内容被裁掉。": "リール、スクロール領域、スクロール スナップ、メーソンリー、インポスター、オーバーレイ、およびスティッキー領域は、コンテンツが切り取られるのを避けるために、印刷時に自動的に平坦化されます。",
  "打印时固定、粘性、全屏和分栏被展平成普通文档流；分隔手柄自动隐藏。": "固定、スティッキー、フルスクリーン、およびカラムナーは、印刷時に通常のドキュメント フローにフラット化されます。仕切りハンドルは自動的に非表示になります。",
  "打印时交互栏、筛选、加载遮罩和浮动按钮隐藏；页头和结果页展平，错误说明与请求编号仍保留。": "インタラクション バー、フィルター、ロード マスク、フローティング ボタンは印刷時に非表示になります。ヘッダーと結果ページはフラット化され、エラーの説明とリクエスト番号は引き続き保持されます。",
  "打印时隐藏窗口 Chrome、活动栏、状态栏、工具栏、Bottom Panel 和所有浮层，展开主内容、Dock 与 Inspector，避免裁切。": "印刷時にウィンドウ Chrome、アクティビティ バー、ステータス バー、ツールバー、ボトム パネル、およびすべてのフローティング レイヤーを非表示にし、トリミングを避けるためにメイン コンテンツ、ドック、およびインスペクターを展開します。",
  "打印隐藏 Tooltip、Popover、Tour、Spotlight、Hotspot 与反馈动作，保留 Tip、Callout、Note 和排错正文。": "ツールヒント、ポップオーバー、ツアー、スポットライト、ホットスポット、フィードバック アクションを印刷および非表示にし、ヒント、吹き出し、メモ、トラブルシューティング テキストを保持します。",
