  "返回的 packed、unpacked 和文件数。1.0.0 以封版的 0.9.0 实测结果为紧邻基线，限制每个产物 raw 增长不超过 2%、gzip/Brotli 不超过 3%，npm 包 packed 不超过 3%、unpacked 不超过 2%、文件数不超过 10%；五个平台产物均拥有直接历史基线。包体测量向上取整到 4 KiB packed 与 64 KiB unpacked，形成不低估真实包体且不受性能报告自包含压缩循环影响的确定性上界。绝对上限或相对上限任一失败都会阻断发布。": "パックされたファイル、アンパックされたファイル、および返されたファイルの数。 1.0.0 では、シールされたバージョン 0.9.0 の実測結果を当面のベースラインとして使用し、各製品の生の増加を 2% 以内、gzip/Brotli の増加を 3% 以内、npm パッケージのパック化を 3% 以内、アンパックされた状態で 2% 以内、およびファイル数を 10% 以内に制限します。 5 つのプラットフォーム製品にはすべて、直接的な過去のベースラインがあります。封入体積の測定値はパック時 4 KiB、アンパック時 64 KiB に切り上げられ、真の封入体積を過小評価せず、パフォーマンス レポートの自己完結型圧縮サイクルの影響を受けない決定的な上限を形成します。絶対キャップまたは相対キャップのいずれかが故障すると、リリースがブロックされます。",
