  "覆盖规则：": "上書きルール:",
  "覆盖基础原子、通用组件、高密度后台、移动端、内容商业化、AI 工作区与桌面 WebView。默认足够克制，组合能力足够宽。": "基本的なアトム、共通コンポーネント、高密度バックエンド、モバイル端末、コンテンツの商用化、AI ワークスペース、デスクトップ WebView をカバーします。デフォルトも十分に抑えられており、組み合わせの幅も十分に広い。",
  "覆盖目录、SKU、购物车、结算、履约、支付、订单、订阅、账单、退款和税费。": "カタログ、SKU、カート、チェックアウト、フルフィルメント、支払い、注文、サブスクリプション、請求、返金、税金を対象としています。",
