  "覆盖全部根类、业务字段组、动态增删、条件显示、容器响应、RTL 与打印。": "すべてのルート クラス、ビジネス フィールド グループ、動的な追加と削除、条件付き表示、コンテナ応答、RTL、および印刷をカバーします。",
