  "覆盖全局、层级、选择、菜单、页内、流程、移动与桌面导航，并可直接测试键盘和右键交互。": "グローバル、階層、選択、メニュー、ページ内、プロセス、モバイルおよびデスクトップのナビゲーションをカバーし、キーボードと右クリックの操作を直接テストできます。",
