  "更新、权限、文件选择、托盘、多窗口、深链、单实例和崩溃恢复都要求业务或宿主返回真实结果；组件只提供可预测的展示、事件、焦点和状态结构。": "更新、権限、ファイル選択、トレイ、マルチウィンドウ、ディープチェーン、シングルインスタンス、およびクラッシュリカバリはすべて、ビジネスまたはホストが実際の結果を返す必要があります。コンポーネントは、予測可能なプレゼンテーション、イベント、フォーカス、状態構造のみを提供します。",
