  "接受": "同意する",
  "接受字符串或字符串数组": "文字列または文字列の配列を受け入れます",
  "接受组件名、AngularJS 指令名或 ESM 导出名，并由 506 项联合类型约束；未知名称会立即抛错。同一 AngularJS 实例、模块名和等价选项重复安装是幂等的，不同组件子集、依赖或初始化选项使用同名模块时会明确报错，防止静默得到半注册模块。": "506 個の共用体タイプによって制限されたコンポーネント名、AngularJS ディレクティブ名、または ESM エクスポート名を受け入れます。不明な名前を指定すると、すぐにエラーがスローされます。同じ AngularJS インスタンス、モジュール名、および同等のオプションを繰り返しインストールすると、冪等になります。異なるコンポーネントのサブセット、依存関係、または初期化オプションが同じ名前のモジュールを使用する場合、半登録されたモジュールをサイレントに取得することを防ぐためにエラーが明示的に報告されます。",
  "结构完整性": "構造の完全性",
