  "可复用筛选条件": "再利用可能なフィルター条件",
  "可关闭组件自动初始化， 方便由页面级运行时统一接管。显式传入的行为 data attribute 优先于生成默认值。": "ページレベルのランタイムによる統合テイクオーバーを容易にするために、コンポーネントの自動初期化をオフにすることができます。データ属性を明示的に渡す動作は、デフォルト値の生成よりも優先されます。",
  "可滚动区域应可被键盘聚焦并提供可访问名称；Reduced Motion 会取消原语的平滑滚动。": "スクロール可能な領域はキーボードでフォーカス可能であり、アクセス可能な名前を提供する必要があります。 Reduced Motion は、プリミティブのスムーズなスクロールを抑制します。",
  "可机器验证": "マシン検証可能",
  "可切换公共网站、Dashboard、CRM、行业门户与状态中心预览。": "切り替え可能な公開 Web サイト、ダッシュボード、CRM、業界ポータル、ステータス センターのプレビュー。",
  "可取消 Before 事件、Approved/Rejected/Cancelled、Reset API": "イベント前にキャンセル可能、承認/拒否/キャンセル、API をリセット",
  "可取消流程守卫": "プロセスガードを解除できるようになりました",
  "可使用": "在庫あり",
  "可选索引文本": "オプションの索引テキスト",
  "可以跨 32 种页面复用，保证 AI 在换行业时不改变基础语法。": "は 32 種類のページにわたって再利用できるため、業界が変わっても AI の基本構文が変わらないことが保証されます。",
  "可用工具类包括": "利用可能なツール クラスは次のとおりです",
  "可用值": "利用可能な値",
  "可直接测试 App Bar、Bottom Navigation、Swipe Tabs、Swipe Actions、Infinite Load、Action/Filter Sheet 与移动选择器。": "アプリバー、ボトムナビゲーション、スワイプタブ、スワイプアクション、無限ロード、アクション/フィルターシート、モバイルセレクターの直接テスト。",
  "可直接测试排序、选择、展开、列显隐、搜索、视图切换、移动堆叠表和键盘网格。": "並べ替え、選択、展開、列の表示/非表示、検索、ビューの切り替え、積み重ねられたテーブルの移動、およびキーボード グリッドを直接テストできます。",
  "可直接测试全选、反选、范围选择、Transfer、Picker、Cascader、Saved Choice 和动态 Builder。": "すべて選択、逆選択、範囲選択、転送、ピッカー、カスケード、保存された選択肢、および動的ビルダーを直接テストできます。",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 326,064 B raw、50,126 B gzip、26,381 B Brotli；单个": "AI、コード ジェネレーター、ドキュメント ツールで直接読み取り可能。完全に圧縮されたパッケージの実測値は、raw で 326,064 B、gzip で 50,126 B、Brotli で 26,381 B です。独身",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包实测为 404,094 B raw、59,499 B gzip、29,785 B Brotli；单个": "AI、コード ジェネレーター、ドキュメント ツールで直接読み取り可能。完全な圧縮パッケージの実測値は、raw 404,094 B、gzip 59,499 B、Brotli 29,785 B です。独身",
  "可直接供 AI、代码生成器和文档工具读取。全量压缩包预算为 328,220 B raw、51,602 B gzip、26,926 B Brotli；单个": "AI、コード ジェネレーター、ドキュメント ツールで直接読み取り可能。完全な圧縮パッケージの予算は、raw 328,220 B、gzip 51,602 B、Brotli 26,926 B です。独身",
