  "框架提供焦点样式、减少动效、高对比和 Forced Colors 基础，但语义名称与内容顺序仍由页面作者负责。": "このフレームワークは、フォーカス スタイル、動きの軽減、ハイ コントラスト、および強制カラーの基盤を提供しますが、セマンティックな名前付けとコンテンツの順序はページ作成者の責任となります。",
  "扩展": "拡張子",
  "了解发布状态": "リリースステータスを理解する",
  "类。": "クラス。",
  "类必须出现在“CSS 全量 API”或“工具类”清单；每个组件、运行时和页面配方还必须出现在各自目录。构建校验会逐文件计算 SHA-256，避免目录落后于源码。": "クラスは CSS フル API またはツール クラスのリストに表示される必要があります。各コンポーネント、ランタイム、およびページ レシピも、それぞれのディレクトリに存在する必要があります。ビルド検証では、ディレクトリがソース コードから遅れることを避けるために、ファイルごとに SHA-256 を計算します。",
  "类名": "クラス名",
  "类型，并保留默认语义标签、选择器、状态、部件、行为、平台与无障碍元数据。静态 SSR 阶段直接输出完整 HTML，建立交互连接后才挂载 DOM 行为；参数签名改变会刷新挂载，组件释放时会注销监听器。": "デフォルトのセマンティックタグ、セレクター、状態、ウィジェット、動作、プラットフォーム、およびアクセシビリティメタデータを入力して保持します。静的 SSR フェーズは完全な HTML を直接出力し、対話型接続の確立後にのみ DOM 動作をマウントします。パラメーターの署名を変更するとマウントが更新され、コンポーネントがリリースされるとリスナーはログアウトされます。",
  "类型、所有者、校验值和版权": "タイプ、所有者、チェック値、および著作権",
  "类型安全监听 gardener:* 事件": "gardener:* イベントのタイプ セーフ リスニング",
  "离线横幅": "オフライン バナー",
