  "刘海屏与 Home Indicator 自动保护。": "ノッチとホーム インジケーターの自動保護。",
  "浏览器支持时继承父网格轨道": "ブラウザがサポートしている場合は親グリッド トラックを継承します",
  "流程与文档": "プロセスとドキュメント",
  "流式消息、工具、Agent、Artifact 与生成状态。": "メッセージ、ツール、エージェント、アーティファクト、ビルド状態のストリーミング。",
  "六个新增声明式行为": "6 つの新しい宣言的動作",
