  "路由失效、搜索和首页入口": "ルーティングの失敗、検索およびホームページのエントリ",
  "逻辑方向属性": "論理方向属性",
  "逻辑方向属性覆盖 RTL；Reduced Motion 停止同步脉冲；Forced Colors 为当前 Activity/Tab/Command 提供明确轮廓。": "論理方向属性が RTL をオーバーライドします。 Reduced Motion は同期パルスを停止します。強制カラーは、現在のアクティビティ/タブ/コマンドの輪郭を明確に示します。",
  "逻辑方向属性支持 RTL；Reduced Motion 关闭位移过渡；Forced Colors 强化选中轮廓；打印自动展平外壳。": "論理方向属性は RTL をサポートします。 Reduced Motion はディスプレイスメントのトランジションをオフにします。強制カラーは、選択した輪郭を強調します。印刷するとシェルが自動的に平らになります。",
  "没有": "なし",
  "没有结果": "結果なし",
  "没有匹配的 {framework} 组件。": "一致する {framework} コンポーネントがありません。",
  "没有匹配的 CSS 接口。": "一致する CSS インターフェイスがありません。",
  "没有匹配的工具类。": "一致するツール クラスがありません。",
  "没有匹配的组件。": "一致するコンポーネントがありません。",
  "媒体上叠工具、标注、状态；align / justify / margin": "メディア オーバーレイ ツール、注釈、ステータス。整列/両端揃え/マージン",
  "媒体资产工作台与详情栏": "メディア アセット ワークベンチと詳細バー",
  "每份自定义构建清单还会为可读 CSS、压缩 CSS、Source Map 和随包复制的 Tauri/Electron 适配器生成 SHA-256 与标准 SRI。接收方无需依赖构建机器，即可逐文件验证交付内容是否完整且未被替换。": "各カスタム ビルド マニフェストは、読み取り可能な CSS、圧縮 CSS、ソース マップ、およびパッケージとともにコピーされた Tauri/Electron アダプター用の SHA-256 および標準 SRI も生成します。受信者は、ビルド マシンに依存せずに、配信が完了し、置き換えられていないことをファイルごとに確認できます。",
  "每个 CSS 组件都有对应的": "各 CSS コンポーネントには対応する",
  "每个公共组件都能解析到完整所属包，并明确列出连带包含项。": "各パブリック コンポーネントは、明示的なインクルージョンがリストされた、それが属する完全なパッケージに解決されます。",
