  "默认白色 Surface、1px 边框与 4px 小圆角；大圆角和强阴影不是移动端默认。": "デフォルトの白いサーフェス、1 ピクセルの境界線と 4 ピクセルの小さな丸い角。大きな丸い角と強い影はモバイルのデフォルトではありません。",
