  "全部模式支持逻辑方向、RTL、Reduced Motion、Forced Colors 和打印；打印时隐藏可变更选择状态的控制，并保留结果摘要。": "論理方向、RTL、縮小モーション、強制カラー、および印刷がすべてのモードでサポートされています。選択状態を変更するコントロールは印刷時に非表示になり、結果の概要は保持されます。",
