  "上表列出 12 个主要 CSS/Runtime 入口；预算文件还逐项覆盖 2 个桌面适配器、28 个组件包，共 42 个正式压缩产物，没有使用笼统的共享上限替代单产物检查。": "上の表には、12 個の主要な CSS/ランタイム エントリがリストされています。また、予算書には、単一製品の検査に代わる一般的な共有キャップを使用せずに、2 つのデスクトップ アダプタ、28 のコンポーネント パッケージ、合計 42 の正式に圧縮された製品の対象範囲が項目化されています。",
