  "使用": "使用する",
  "使用 {theme} 主题": "{theme} テーマを使用",
  "使用 704px 容器折叠；文件浏览、媒体详情、图片编辑器、文档缩略图、Markdown 双栏和版本对比均有移动布局。": "704 ピクセルのコンテナ折りたたみを使用します。ファイル ブラウザ、メディアの詳細、画像エディタ、ドキュメントのサムネイル、Markdown の 2 列、バージョン比較はすべてモバイル レイアウトを備えています。",
  "使用 Ajv 2020-12 执行 48 个标准验证用例，覆盖十份发布/配置文档、未知根字段、十类未知嵌套字段、十类缺失嵌套必填字段、跨 Schema 引用、JavaScript 标识符、SHA-256 格式、基线回归状态和旧组件 Schema 兼容别名；": "Ajv 2020-12を使用して48の標準検証ユースケースを実行し、10のリリース/構成ドキュメント、不明なルートフィールド、10種類の不明なネストされたフィールド、10種類の欠落したネストされた必須フィールド、スキーマ間参照、JavaScript識別子、SHA-256形式、ベースライン回帰ステータス、レガシーコンポーネントスキーマ互換エイリアスをカバーしました。",
  "使用 gzip level 9 与 Brotli quality 11，对全部 42 个正式压缩产物同时计算 raw、gzip 和 Brotli，并检查全量 CSS、Runtime 的压缩比例，以及": "gzip レベル 9 と Brotli 品質 11 を使用して、42 の公式圧縮製品すべての raw、gzip、Brotli を同時に計算し、完全な CSS、ランタイム、および",
  "使用 Node.js 内置测试运行器和 Happy DOM，对公共清单中的全部 66 种行为逐项双向比对真实实例成员，并验证初始化、幂等性、销毁和重新初始化；同时覆盖 MutationObserver 的动态节点、动态属性、子树移除、作用域销毁、多行为共存、全局销毁和初始化事件冒泡。": "Node.js 組み込みテスト ランナーと Happy DOM を使用して、公開リスト内の 66 個の動作すべてについて実際のインスタンス メンバーを双方向に比較し、初期化、べき等、破棄、再初期化を検証します。 MutationObserver の動的ノード、動的属性、サブツリーの削除、スコープの破棄、複数の動作の共存、グローバルの破棄、および初期化イベントのバブリングをカバーします。",
  "使用 TypeScript 严格模式编译真实消费者，覆盖默认及命名导出、行为工厂、Toast、实例查询和两类桌面桥接。": "TypeScript の厳密モードを使用して実際のコンシューマをコンパイルし、デフォルトおよび名前付きエクスポート、動作ファクトリー、トースト、インスタンス クエリ、および 2 種類のデスクトップ ブリッジをカバーします。",
