  "视口响应 · 容器响应 · 逻辑方向 · 打印展平 · 桌面工作台": "ビューポートの応答性 · コンテナーの応答性 · 論理方向 · 印刷のフラット化 · デスクトップ ワークベンチ",
  "视口小于 768px 时，多栏、Master / Detail 和检查器布局按语义顺序纵向排列；Dock 默认只保留主区，可用": "ビューポートが 768 ピクセルより小さい場合、複数列、マスター/詳細、およびインスペクターのレイアウトが意味的な順序で垂直に配置されます。 Dock はデフォルトでメイン領域のみを保持し、使用可能です",
  "视口最小宽度": "ビューポートの最小幅",
