  "试用": "トライアル",
  "是 Gardener CSS 1.0.0 的官方 AngularJS 1.x 遗留系统适配层，当前版本为": "は Gardener CSS 1.0.0 の公式 AngularJS 1.x レガシー システム アダプテーション レイヤーであり、現在のバージョンは",
  "是 Gardener CSS 1.0.0 的官方 Razor Class Library，当前版本为": "は Gardener CSS 1.0.0 の公式 Razor クラス ライブラリであり、現在のバージョンは",
  "是 Gardener CSS 1.0.0 的官方 React 适配层，当前版本为": "は Gardener CSS 1.0.0 の公式 React アダプテーション レイヤーであり、現在のバージョンは",
  "是 Gardener CSS 1.0.0 的官方 Vue 3 适配层，当前版本为": "は Gardener CSS 1.0.0 の公式 Vue 3 アダプテーション レイヤーであり、現在のバージョンは",
  "是给生成器使用 Gardener 的约束。前者提供界面组件，后者规定选能力、配方、组件和工具类的顺序。": "は、ジェネレーターで Gardener を使用するための制約です。前者はインターフェイス コンポーネントを提供し、後者は機能、レシピ、コンポーネント、ツール クラスが選択される順序を指定します。",
  "是公共命名与程序接口的规范清单，完整登记 CSS 层、包入口、主题属性、JavaScript 导出、行为、事件、桌面适配器和兼容字段。": "は、CSS レイヤー、パッケージ エントリ、テーマ プロパティ、JavaScript エクスポート、動作、イベント、デスクトップ アダプター、および互換性フィールドを完全に登録した、公開命名およびプログラミング インターフェイスの正規リストです。",
  "是五个公共区域；": "は 5 つの共通領域です。",
  "是预压缩单文件入口。SSR 导入不访问浏览器全局对象，行为只在组件挂载后初始化，因此可用于服务端渲染与 Hydration。": "は、事前圧縮された単一ファイル エントリです。 SSR インポートはブラウザーのグローバル オブジェクトにアクセスせず、動作はコンポーネントがマウントされた後にのみ初期化されるため、サーバー側のレンダリングとハイドレーションに使用できます。",
  "适合 WebView": "WebView に適しています",
  "适用场景": "該当するシナリオ",
  "释放监听器、计时器和实例引用。": "リスナー、タイマー、インスタンス参照を解放します。",
  "收藏": "コレクション",
  "收录完整 42 个颜色主题，默认保持白底 Light 与小圆角 small。 5 个作用域服务为": "42 色のテーマが含まれており、デフォルトの白の背景が明るく、小さな丸い角が付いています。 5つのスコープサービスは次のとおりです。",
  "收入": "収入",
