  "手势、按钮与 Escape 均可操作。": "ジェスチャー、ボタン、エスケープがすべて利用可能です。",
  "手势提示": "ジェスチャープロンプト",
  "手势只增强效率：Pull Refresh 有刷新按钮路径，Infinite Load 有“加载更多”，Swipe Actions 有 Toggle，Wheel Picker 支持键盘。": "ジェスチャは効率を高めるだけです。プル リフレッシュには更新ボタン パスがあり、無限ロードには「さらにロード」があり、スワイプ アクションにはトグルがあり、ホイール ピッカーにはキーボード サポートがあります。",
  "首次密码、资料、组织与安全偏好": "初回パスワード、情報、組織およびセキュリティ設定",
