  "授权同意": "承認と同意",
  "舒适、标准和紧凑密度": "快適、標準、コンパクトな密度",
  "输出前校验端点、键盘、焦点、状态、RTL、打印和高对比环境。": "出力前にエンドポイント、キーボード、フォーカス、ステータス、RTL、印刷、およびハイコントラスト環境を確認してください。",
  "输入发送到 +86 138****6608 的验证码": "+86 138****6608 に送信された確認コードを入力してください",
  "输入类名、完整选择器、CSS 属性、值或响应条件。为避免一次渲染 11,498 项，至少输入两个字符后分批显示，每次 100 项；输入": "クラス名、完全なセレクター、CSS プロパティ、値、または応答条件を入力します。一度に 11,498 個のアイテムがレンダリングされるのを避けるには、一度に 100 個のアイテムをバッチで表示する前に、少なくとも 2 文字を入力します。入る",
  "输入命令": "コマンドを入力してください",
  "输入命令或文件名": "コマンドまたはファイル名を入力してください",
  "属性": "プロパティ",
  "属性 / 触发": "プロパティ/トリガー",
  "属性、样式、审计、上下文信息": "プロパティ、スタイル、監査、コンテキスト情報",
  "属性的真实源码命中，将 506 个组件解析到一个或多个完整所属包，而不是截取单个选择器，因此伪类、状态、动画、子部件、容器查询和依赖规则不会丢失。": "プロパティの実際のソース コード ヒット。個々のセレクターを切り捨てるのではなく、506 コンポーネントを 1 つ以上の完全な所属パッケージに解決するため、疑似クラス、状態、アニメーション、サブパーツ、コンテナ クエリ、依存関係ルールが失われません。",
