  "搜索 GButton、dialog、选择器、类别、状态、行为或平台": "GButton、ダイアログ、セレクター、カテゴリ、状態、動作、またはプラットフォームを検索します",
  "搜索 GButton、dialog、选择器、类别、状态或平台": "GButton、ダイアログ、セレクター、カテゴリ、状態、またはプラットフォームを検索します",
