  "缩进层级、父子行展开": "インデントレベル、親子行展開",
  "缩略图、名称、属性和快捷动作": "サムネイル、名前、プロパティ、クイック アクション",
  "缩略图网格与媒体多选": "サムネイル グリッドとメディアの複数選択",
  "所有 32 模式均进入组件 Manifest 和动态组件目录；CSS 源码完整 API 也会列出模块、选择器、变量和状态。": "32 のモードすべてがコンポーネント マニフェストと動的コンポーネント ディレクトリに入ります。 CSS ソースの完全な API には、モジュール、セレクター、変数、状態もリストされています。",
  "所有结构采用逻辑方向属性并支持 RTL；Forced Colors 提供选择轮廓；打印隐藏数据操作，展开详情和层级行，并移除滚动裁切。": "すべての構造は論理方向属性を採用し、RTL をサポートします。強制カラーは選択範囲のアウトラインを提供します。非表示のデータ操作を印刷し、詳細行と階層行を展開し、スクロール クリッピングを削除します。",
  "所有开始、结束和操作对齐使用逻辑方向；Floating Action Bar、Back to Top 同时读取设备安全区。": "すべての開始、終了、およびアクションの位置合わせでは論理方向が使用されます。フローティング アクション バー、[トップに戻る] もデバイスのセーフ エリアを読み取ります。",
  "所有模式覆盖键盘、RTL、Reduced Motion、Forced Colors 与打印；移动结算尊重 Safe Area，打印隐藏购买动作并保留订单、发票和税费信息。": "すべてのモードはキーボード、RTL、Reduced Motion、Forced Colors、および印刷をカバーします。モバイル請求ではセーフ エリアが尊重され、印刷により購入アクションが非表示になり、注文、請求書、税金情報が保持されます。",
  "所有模式使用白色 Surface、1px 边框和4px小圆角；在 960/704/512px 容器宽度下折叠 Artifact、Sidebar 与双列模式，并覆盖 RTL、Forced Colors 和打印。": "すべてのモードで白い表面、1 ピクセルの境界線、および 4 ピクセルの小さな丸い角を使用します。コンテナ幅 960/704/512px でアーティファクト、サイドバー、デュアルカラムモードを折りたたみ、RTL、強制カラー、印刷をオーバーライドします。",
  "所有模式使用逻辑方向并覆盖 RTL、Reduced Motion、Forced Colors 和打印；打印隐藏上传与编辑动作，展平滚动区并保留正文和修订信息。": "すべてのモードは論理方向を使用し、RTL、Reduced Motion、Forced Colors、および Print をカバーします。 [印刷] では、アップロードおよび編集アクションが非表示になり、スクロール領域が平坦になり、テキストとリビジョン情報が保持されます。",
  "所有水平语义使用 inline/start/end；Media Object、Bleed、Imposter、Overlay、Reel 和 Scroll Snap 支持 RTL。": "すべての水平セマンティクスはインライン/開始/終了を使用します。メディア オブジェクト、ブリード、インポスター、オーバーレイ、リール、およびスクロール スナップは RTL をサポートします。",
  "所有图片有符合目的的": "すべての画像が目的に適合しています",
  "所有样式覆盖 RTL、Reduced Motion、Forced Colors 与打印。打印隐藏密码、Provider、倒计时和敏感操作，只保留必要的安全审计信息。": "すべてのスタイルは、RTL、Reduced Motion、Forced Colors、および印刷をカバーします。隠されたパスワード、プロバイダー、カウントダウン、機密操作を印刷し、必要なセキュリティ監査情報のみを保持します。",
  "所有原生 attributes、DOM 事件和 slots 均透传。组件模板 Ref 统一公开": "すべてのネイティブ属性、DOM イベント、スロットがパススルーされます。コンポーネントテンプレート参照統一開示",
  "所有组合使用逻辑方向属性；Input Group、Money、Unit、字段动作和 Sticky Actions 在 RTL 下保持正确首尾关系。": "すべての組み合わせで論理方向属性が使用されます。入力グループ、マネー、ユニット、フィールド アクション、およびスティッキー アクションは、RTL の下で正しい先頭と末尾の関係を維持します。",
  "锁屏": "ロック画面",
  "套餐、版本和能力横向比较": "パッケージ、バージョン、機能の水平比較",
  "提供 640px 容器折叠；移动端 Picker Panel 自动成为底部面板，Batch Toolbar 避让安全区。": "640 ピクセルのコンテナ折りたたみを提供します。モバイル ピッカー パネルが自動的に下部パネルになり、バッチ ツールバーは安全領域を回避します。",
  "提供 Unicode 搜索、网格/列表切换、单项选择、方向键、Home、End、Enter 和 Space，并发布选择事件。": "Unicode 検索、グリッド/リスト切り替え、単一選択、矢印キー、Home、End、Enter、Space を提供し、選択イベントを公開します。",
  "提供传统 12 栅格。两者都使用原生 CSS Grid、逻辑方向和统一断点，不依赖负边距。": "従来の 12 グリッドを提供します。どちらもネイティブ CSS グリッド、論理方向、統合されたブレークポイントを使用し、負のマージンに依存しません。",
  "提供每个页面的端、部件、运行时和用途；": "各ページのターミナル、ウィジェット、ランタイム、および目的を提供します。",
  "提供适合编辑器、AI 工具和超级 CMS 的固定视口布局。通过": "エディター、AI ツール、スーパー CMS に適した固定ビューポート レイアウトを提供します。パス",
