  "同一整页契约可切换企业、个人、医疗、金融或公共服务主题。": "同じ全ページ契約書で、ビジネス、個人、医療、金融、または公共サービスのトピックを切り替えることができます。",
  "统一": "統一",
  "统一垂直节奏；default、bordered": "統一された垂直リズム。デフォルト、枠付き",
  "统一单选/多选、Unicode 搜索、Chip 删除、隐藏字段输出、方向键、Home、End、Enter、Space、Escape 和点击外部关闭。": "統合された単一/複数選択、Unicode 検索、チップ削除、隠しフィールド出力、矢印キー、Home、End、Enter、Space、Escape を押して外側をクリックして閉じます。",
  "统一的": "統一",
  "统一工具命令、Ctrl/Command 快捷键、字符与词数；富文本、Markdown、代码和区块编辑器共用协议。": "ツール コマンド、Ctrl/Command ショートカット、文字数と単語数を統合します。リッチ テキスト、マークダウン、コード、ブロック エディターの一般的なプロトコル。",
  "统一命名": "統一された命名",
  "统一业务实体选择器": "統合ビジネスエンティティセレクター",
  "统一页面标题、说明、元数据和操作。": "ページのタイトル、説明、メタデータ、アクションを統合します。",
  "统一页面状态结构": "ページのステータス構造を統合する",
  "统一页头、工具栏、命令栏、筛选与批量操作，再把 Loading、Empty、Error、403、404、500、离线和维护状态准备完整。AI 生成的页面不再只有“正常数据”这一种情况。": "ページ ヘッダー、ツールバー、コマンド バー、フィルタリング、バッチ操作を統合し、読み込み中、空、エラー、403、404、500、オフライン、メンテナンスのステータスを完全に準備します。 AI によって生成されたページはもはや単なる「通常のデータ」ではありません。",
