  "先建立租户与身份边界，再组织内容工作流、Dashboard 和门户页面。": "コンテンツ ワークフロー、ダッシュボード、ポータル ページを整理する前に、テナントと ID の境界を確立します。",
  "先判断导航范围（全局、局部、层级或页内），再判断方向和终端；Tabs 只切换同一上下文内的视图，Breadcrumb 只表达位置，Pagination 只表达结果集翻页，不应互相替代。": "まずナビゲーション範囲 (グローバル、ローカル、階層、またはページ内) を決定し、次に方向とターミナルを決定します。タブは同じコンテキスト内でビューを切り替えるだけ、ブレッドクラムは位置を表すだけ、ページネーションは結果セットのページ送りを表すだけであり、相互に置き換えるべきではありません。",
  "先判断数据形态，再判断操作强度。少量静态属性用 Description List 或 Key Value；多记录用 List 或 Table；单元格需要键盘移动和编辑时才使用 Data Grid；层级数据使用 Tree 或 Tree Table；趋势和比较先提供可读数值，再增加图形。": "最初にデータ形式を決定し、次に操作強度を決定します。少数の静的属性には説明リストまたはキー値を使用します。複数のレコードにはリストまたはテーブルを使用します。データ グリッドは、セルにキーボードの移動と編集が必要な場合にのみ使用します。階層データにはツリーまたはツリー テーブルを使用します。傾向と比較では、最初に読み取り可能な値が提供され、次にグラフィックが追加されます。",
