  "颜色主题与中性色、字体、形状、密度、层次、动效、平台和操作系统正交组合。这里始终保持白色浅色界面，只切换品牌主色。": "カラーテーマは、ニュートラル、フォント、形状、濃度、レイヤー、アニメーション、プラットフォーム、オペレーティング システムと直交して組み合わされます。ここでは白と明るいインターフェースが常に維持され、メインのブランドカラーのみが切り替わります。",
  "颜色主题只负责品牌主色；显示模式与其他主题轴相互独立。本站固定使用 Light，以保持白色文档体验，但框架同时提供 Dark、System 与 High Contrast。": "カラーテーマはメインのブランドカラーのみを担当します。表示モードは他のテーマ軸から独立しています。このサイトでは、白​​いドキュメント エクスペリエンスを維持するためにライトを使用していますが、フレームワークはダーク、システム、およびハイ コントラストも提供します。",
