  "页面不能只实现正常数据态。至少要明确 Loading、Empty、Error；面向路由和完整应用时还应准备 403、404、500、Offline 和 Maintenance。Gardener 为这些状态提供相同的内容、视觉、详情、操作和帮助部件。": "ページは通常のデータ状態のみを実装できません。少なくとも「Loading」、「Empty」、「Error」が明確である必要があります。ルーティングおよび完全なアプリケーションの場合は、403、404、500、オフライン、およびメンテナンスも準備する必要があります。 Gardener は、これらの状態に対して同じコンテンツ、ビジュアル、詳細、アクション、およびヘルプ ウィジェットを提供します。",
