  "营销、个人和内容页使用自然文档滚动；Dashboard 与工作台允许高密度多栏；医疗、金融和政务只是 UI 契约，不替代法规、身份验证、隐私、审计和后端业务规则。": "マーケティング、個人、およびコンテンツのページでは、自然なドキュメント スクロールが使用されます。ダッシュボードとワークベンチでは、高密度の複数の列が可能です。医療、金融、政府は UI 契約のみであり、規制、認証、プライバシー、監査、バックエンド ビジネス ルールに代わるものではありません。",
