  "用于直接读取上下文。默认仍是白色 Light 与小圆角，不会自动启用深色主题。": "コンテキストを直接読み取る場合。デフォルトは依然として白いライトで、小さな丸い角があり、ダークテーマは自動的に有効になりません。",
