  "与 Node.js": "Node.js を使用",
  "与安全 preload，只暴露 Minimize、Maximize/Restore、Close 等白名单方法；不要开启 Node Integration，也不要把任意 IPC 通道暴露给页面。": "セキュリティ プリロードでは、最小化、最大化/復元、閉じるなどのホワイトリスト メソッドのみを公開します。ノード統合を有効にせず、IPC チャネルをページに公開しないでください。",
