  "原生 input 后备；发出": "ネイティブ入力フォールバック。放出された",
  "原生 input、textarea 和 select 的模型语义仍由 AngularJS 自己管理，适配层不会覆盖": "ネイティブ入力、テキストエリア、選択のモデル セマンティクスは依然として AngularJS 自体によって管理されており、アダプテーション レイヤーではカバーされません。",
  "原生 input/change 自动去重": "ネイティブ入力/変更の自動重複排除",
  "原生标题栏、窗口按钮、菜单和活动栏只是起点；文档标签、可调分栏、Dock、检查器、命令面板、文件选择、托盘、多窗口、后台任务、更新、权限与崩溃恢复均已有稳定组合，可直接落地 Tauri 与 Electron。": "ネイティブのタイトル バー、ウィンドウ ボタン、メニュー、およびアクティビティ バーは出発点にすぎません。ドキュメント ラベル、調整可能な列、Dock、インスペクター、コマンド パネル、ファイル選択、トレイ、マルチ ウィンドウ、バックグラウンド タスク、更新、アクセス許可、クラッシュ リカバリがすべて安定して組み合わされており、Tauri と Electron に直接実装できます。",
  "原生表单和自定义 Gardener 事件均支持": "ネイティブ フォームとカスタム Gardener イベントの両方がサポートされています",
  "原生权限请求、网络状态、数据加载、支付、认证和媒体缩放由业务或宿主实现；Gardener 提供稳定视觉、状态、事件与无障碍接口，不伪造结果。": "ネイティブの許可リクエスト、ネットワークステータス、データロード、支払い、認証、およびメディアスケーリングは企業またはホストによって実装されます。 Gardener は、結果を偽造することなく、安定したビジョン、ステータス、イベント、アクセス可能なインターフェイスを提供します。",
