  "阅读宽度、水平或内容居中；max / gutter": "読み取り幅、レベル、またはコンテンツ センター。最大/ガター",
  "阅读文档": "ドキュメントを読む",
  "允许后续 1.x 新增，禁止无迁移路径的删除；在 1.0.0 稳定切点还会反向检查已有入口是否漏记。废弃入口至少保留两个次版本，并只能在新的主版本移除。其闭合结构由": "後続の 1.x の追加は許可し、移行パスなしの削除は禁止します。 1.0.0 安定カットオフ ポイントでは、既存のエントリも逆にチェックされ、欠落していないかどうかが確認されます。非推奨のエントリは少なくとも 2 つのマイナー バージョンに残り、新しいメジャー バージョンでのみ削除できます。その閉鎖構造は次のもので構成されています。",
  "允许写入页面模板？": "ページ テンプレートへの書き込みを許可しますか?",
  "允许一次": "1 回のみ許可",
  "运行环境": "動作環境",
  "运行时": "ランタイム",
  "运行时，根据滚动位置显示，点击后平滑返回顶部；Reduced Motion 环境自动使用即时滚动。": "実行時、表示はスクロール位置に基づいて行われ、クリックするとスムーズに先頭に戻ります。 Reduced Motion 環境では、インスタント スクロールが自動的に使用されます。",
  "运行时、可访问性与环境规则": "ランタイム、アクセシビリティ、および環境のルール",
  "运行时测试门禁（0.4.0 起）": "実行時のアクセス制御のテスト (0.4.0 以降)",
  "运行时框架无关，通过": "ランタイム フレームワークに依存せず、合格しました",
  "运行时事件": "ランタイム イベント",
  "运行时维护状态": "ランタイムメンテナンスステータス",
  "运行时行为新增或改名时，公共 API、示例/补充夹具和逐行为测试必须同步，否则测试会因缺少夹具、实例或成员而失败。": "ランタイム動作を追加または名前変更する場合、パブリック API、サンプル/補足フィクスチャ、および動作ごとのテストを同期する必要があります。同期しないと、フィクスチャ、インスタンス、またはメンバーが欠落しているためにテストが失敗します。",
  "运行时与环境规则": "ランタイムと環境のルール",
  "运行中": "ランニング",
  "在 200% 缩放、RTL、Reduced Motion、Forced Colors 下仍可操作。": "200% スケーリング、RTL、縮小モーション、強制カラーでも引き続き動作します。",
  "在 704px 折叠详情/结算双栏，在 480px 重排行项目与选择卡；视口查询作为没有容器上下文时的兜底。": "704 ピクセルで詳細/チェックアウトの 2 列を折りたたみ、品目を並べ替えて 480 ピクセルでカードを選択します。コンテナコンテキストがない場合のフォールバックとしてのビューポートクエリ。",
  "在视口或": "ビューポート内または",
  "在整个": "全体を通して",
  "增加可运行示例与验证输入。": "実行可能なサンプルと検証入力を追加しました。",
  "增加数量": "数量を増やす",
  "栅格": "グリッド",
  "粘性辅助栏": "粘着補助バー",
  "粘性购买栏": "スティッキーバイバー",
  "展开": "展開する",
  "展开任一模块可查看该文件公开的类、Token、状态、数据属性和关键帧。生成型工具模块链接到独立的 11,498 项清单。": "モジュールを展開すると、ファイルによって公開されるクラス、トークン、状態、データ属性、およびキーフレームが表示されます。生成ツール モジュールは、別の 11,498 アイテムのインベントリにリンクします。",
