  "账号、租户与身份是不同概念，分别使用 Chooser/Switcher，避免在多组织 CMS 中误操作。": "アカウント、テナント、アイデンティティは異なる概念です。複数組織CMSでの誤操作を避けるために、Chooser/Switcherをそれぞれ使用してください。",
  "账号安全中心": "アカウント セキュリティ センター",
