  "账号与租户选择": "アカウントとテナントの選択",
  "找回密码": "パスワードを取得する",
  "这段说明有帮助吗？": "この説明は役に立ちましたか?",
  "这是我": "これが私です",
  "正式 CSS 与 JavaScript 使用 esbuild 做语法级压缩，不使用正则替换；主压缩入口和每次自定义构建生成可追溯的外部 Source Map。压缩 CSS 使用不随版本变化的稳定 MIT banner，避免纯版本文本扰动 Brotli 基线，未压缩 CSS 与 Runtime 仍提供精确版本。": "正式な CSS と JavaScript は、通常の置換を使用せずに、構文レベルの圧縮に esbuild を使用します。メインの圧縮エントリと各カスタム ビルドは、追跡可能な外部ソース マップを生成します。圧縮 CSS は、純粋なバージョン テキストが Brotli ベースラインを乱すことを避けるために、バージョンによって変化しない安定した MIT バナーを使用します。非圧縮の CSS とランタイムでも正確なバージョンが提供されます。",
