  "作为父级。列宽类保持相同，AI 只需先确定父级系统。": "を親として使用します。列幅クラスは同じままで、AI は最初に親システムを決定するだけで済みます。",
  "作为兼容别名保留。按组件名构建时，构建器依据类选择器与": "互換性のあるエイリアスとして予約されています。コンポーネント名でビルドする場合、ビルダーはクラスセレクターと",
  "作者可使用的 309 个属性被划分为上方行为契约中的 66 个行为入口、166 个结构/动作选择器和 77 个附加配置属性；另有 27 个由运行时维护的状态属性。状态属性可能同时作为初始配置读取，但作者可用的前三组彼此互斥，不会重复计数。": "作成者が利用できる 309 のプロパティは、上記の動作コントラクト内の 66 の動作エントリ、166 の構造/アクション セレクター、および 77 の追加構成プロパティに分割されています。ランタイムによって維持される 27 の状態プロパティもあります。ステータス プロパティは初期設定として同時に読み込むことができますが、作成者が利用できる最初の 3 つのセットは相互に排他的であり、二重にカウントされません。",
