  "Gardener": "Gardener",
  "Gardener — 为所有界面准备好的 CSS 基础设施": "Gardener — すべてのインターフェイスに対応した CSS インフラストラクチャ",
  "gardener / workspace / overview": "gardener / workspace / overview",
  "Gardener 把基础 CSS、交互组件、业务配方、桌面端适配与机器可读清单放进同一套系统。人可以直接开发，AI 可以准确选用，无需每次重新组织样式。": "Gardener は、基本的な CSS、インタラクティブ コンポーネント、ビジネス レシピ、デスクトップ アダプテーション、および機械可読マニフェストを 1 つのシステムに統合します。人が直接開発することができ、毎回スタイルを再編成することなく、AI が正確に選択して使用することができます。",
  "Gardener 可以只使用 CSS，也可以加载零依赖运行时获得交互行为。完整包默认包含所有主题、组件和工具类。": "Gardener は CSS のみを使用することも、対話型動作のために依存関係のないランタイムをロードすることもできます。完全なパッケージには、デフォルトですべてのテーマ、コンポーネント、ツール クラスが含まれています。",
  "Gardener 是面向人类开发者与 AI 页面生成器的通用 CSS、Vue 3、React、AngularJS 与 Blazor 组件、页面配方及桌面应用基础设施。": "Gardener は、人間の開発者と AI ページ ビルダー向けのユニバーサル CSS、Vue 3、React、AngularJS、Blazor コンポーネント、ページ レシピ、デスクトップ アプリケーション インフラストラクチャです。",
  "Gardener 首页": "Gardener ホームページ",
  "Gardener 完整文档：CSS、Vue 3、React、AngularJS、Blazor、主题、Token、工具类、506 个组件、运行时、完整页面、AI 页面生成及桌面端适配。": "Gardener の完全なドキュメント: CSS、Vue 3、React、AngularJS、Blazor、テーマ、トークン、ツール クラス、506 コンポーネント、ランタイム、完全なページ、AI ページ生成、およびデスクトップの適応。",
  "Gardener 为 AI 提供五层事实来源：公共 API 清单回答“允许使用什么稳定名称与入口”，能力清单回答“行业常规能力是否实现”，组件清单回答“有什么”，工具类清单回答“精确类名是什么”，配方清单回答“复杂页面怎样开始”。": "Gardener は AI に 5 つの層の真実の情報源を提供します。公開 API リストは「使用が許可されている安定した名前とエントリ」、機能リストは「業界の通常の機能が実装されているかどうか」、コンポーネント リストは「そこにあるもの」、ツール クラス リストは「正確なクラス名は何か」、レシピ リストは「複雑なページの開始方法」に答えます。",
  "Gardener 文档": "Gardenerドキュメント",
  "Gardener 移动端组件预览": "Gardener モバイル コンポーネントのプレビュー",
  "Gardener 以 24 栅格作为企业后台、CMS 和精细表单的主兼容协议，同时通过": "Gardener は、エンタープライズ バックエンド、CMS、ファイン フォームの主な互換プロトコルとして 24 ラスターを使用します。",
