  "Public API、组件、工具类、配方与行业能力五类清单，把允许使用的名称、入口、平台、状态和响应条件结构化暴露出来，页面生成过程可以被约束、验证和复现。": "パブリック API、コンポーネント、ツール クラス、レシピ、業界機能の 5 つのカテゴリのリストは、許可された名前、入り口、プラットフォーム、ステータス、および応答条件を構造化された方法で公開します。ページ生成プロセスは、制約、検証、再現できます。",
