  "Sidebar、Switcher、Auto Fit/Fill 本身按可用空间响应，不依赖设备宽度。": "サイドバー、スイッチャー、自動フィット/フィル自体は、デバイスの幅とは関係なく、利用可能なスペースに応じて応答します。",
