  "SKU 的 Disabled、库存的 Low/Out、优惠码的 Invalid、支付的 Success/Error/Pending、退款的 Processing/Complete/Failed 都有独立状态，不能只依赖颜色。": "SKU の無効、在庫の残りわずか/在庫切れ、割引コードの無効、支払いの成功/エラー/保留中、返金の処理/完了/失敗はすべて独立したステータスを持ち、色のみに依存することはできません。",
