  "Sources/Citations 表示引用关系，不自动证明真实性；业务需要保留来源 URL、片段、时间和可访问性，生成内容仍需事实核验。": "出典/引用は引用関係を表しており、信頼性を自動的に証明するものではありません。企業はソース URL、フラグメント、時間、アクセシビリティを保持する必要があり、生成されたコンテンツは引き続き事実確認する必要があります。",
