  "Stack、Cluster、Sidebar、Switcher、Reel、Media Object、Masonry、Bento 等经典模式已经固化为内在响应接口。AI 只需选择意图和少量变量，无需重新发明 Flex、Grid、溢出与安全区规则。": "スタック、クラスター、サイドバー、スイッチャー、リール、メディア オブジェクト、メイソンリー、ベントなどの古典的なパターンが、固有の応答インターフェイスに統合されました。 AI は意図といくつかの変数を選択するだけでよく、フレックス、グリッド、オーバーフロー、安全領域のルールを再発明する必要はありません。",
