  "Tauri v2": "Tauriのv2",
  "Tauri v2 由应用注入 Window API；权限能力、文件系统、Updater、Deep Link、Tray 与多窗口按应用 Capability 配置，不由 CSS 自动申请。": "Tauri v2 はアプリケーションによって Window API に挿入されます。権限機能、ファイル システム、アップデータ、ディープ リンク、トレイ、およびマルチ ウィンドウはアプリケーションの機能に従って構成され、CSS によって自動的に適用されません。",
